#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

int fd; // Existing file descriptor
struct stat statbuf;

// Retrieve metadata for file associated with fd
int result = fstat(fd, &statbuf);

if (result == -1) {
    perror("fstat failed");
} else {
    // Access file size (e.g.)
    off_t size = statbuf.st_size;
    // Access inode number
    ino_t inode = statbuf.st_ino;
}

// Common Errors:
// EBADF: fd is invalid
// EFAULT: statbuf is invalid pointer
// EIO: I/O error during read
